-- Сид календаря событий-триггеров прогноза золота/NAV на Q4-2026 (ARCHITECTURE.md §7).
-- Источник канонического DDL — ARCHITECTURE.md §6.2. Запуск: make ch-sql FILE=sql/events_calendar_q4_2026.sql
-- Вставка идемпотентна: ReplacingMergeTree ORDER BY (event_date, category, title) сворачивает дубли.

CREATE TABLE IF NOT EXISTS events_calendar (
    event_date Date,
    event_time Nullable(String),
    category LowCardinality(String), -- 'fomc','cpi','nfp','eia','wgc','cbr','polyus_ir','moex_rebalance','gov_rf','bank_results'
    title String,
    threshold String,                -- JSON, напр. '{"crack":">50"}'
    status LowCardinality(String) DEFAULT 'pending'  -- pending|done|verified
) ENGINE = ReplacingMergeTree ORDER BY (event_date, category, title);


-- Триггеры DCF-контура: публикации по проекту Сухой Лог (категория polyus_ir).
-- Зачем: график запуска ЗИФ — прямой вход модели выпуска (docs/plans/POLYUS_OUTPUT_MODEL_PLAN.md §6.3).
-- База сегодня — консенсус аналитиков (первая линия 2030, вторая 2031–2032); официальный план
-- компании (2028/2029, https://polyus.com/ru/investors/proekty-rosta/) отстаёт от реальности стройки,
-- поэтому обновлённое ТЭО — единственный источник, которым план заменяется фактом.
-- Пороги сформулированы так, чтобы по событию было ясно: пересчитывать сид выпуска или нет.

-- Еженедельные релизы по средам (ARCHITECTURE.md §7): EIA Weekly Petroleum Status и недельный ИПЦ Росстата.
